(() => {
  'use strict';
  const D = window.MUSIC_MAP_DEMO, A = Object.fromEntries(D.artists.map(a => [a.id,a]));
  const songs = {}, edges = [];
  D.artists.forEach(a => a.songs.forEach((title,i) => { songs[`${a.id}-${i}`] = {id:`${a.id}-${i}`,title,artists:[a.id],missing:a.id==='i'||(a.id==='a'&&i===2)}; }));
  D.cooperation.forEach(([a,b,title],i) => {const id=`co-${i}`;songs[id]={id,title,artists:[a,b]};edges.push({id,a,b,mode:'co',song:id,reason:'共同演唱 · 虚构关系示例'});});
  D.style.forEach(([a,b,reason],i) => edges.push({id:`style-${i}`,a,b,mode:'style',reason}));
  const KEY='musicmap.prototype.v1';
  let db={sessions:[],active:null,page:'home'}, storageError=false;
  try { const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!Array.isArray(parsed.sessions)||parsed.version!==D.version)throw Error('version');if(parsed.sessions.some(s=>!A[s.start]||!Array.isArray(s.path)||s.path.some(p=>!A[p.id])||!Array.isArray(s.saved)||s.saved.some(x=>!songs[x.id])))throw Error('content');db=parsed;}} catch {storageError=true;}
  const app=document.getElementById('app'), modal=document.getElementById('modal'), content=document.getElementById('modal-content');
  let modalState=null, drawer=false, playing=null, playTimer=null, toastTimer=null, undo=null, busy=false, drag=null, suppressClick=0;
  const e = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const current = () => db.sessions.find(s=>s.id===db.active);
  const context = () => db.sessions.find(s=>s.id===modalState?.id)||current();
  const last = s => s.path[s.path.length-1];
  const name = id => A[id]?.name || '未收录艺人';
  const neighbors = s => edges.filter(x=>x.mode===s.mode&&(x.a===last(s).id||x.b===last(s).id));
  const other = (edge,id) => edge.a===id?edge.b:edge.a;
  const uniqueArtists = s => [...new Set([s.start,...s.events.filter(x=>x.type==='move').map(x=>x.to)])];
  const avatar = (id,tiny=false) => `<span class="avatar ${tiny?'tiny':''}" style="--tone:${A[id].color}" aria-hidden="true">${e(name(id).slice(0,1))}</span>`;
  const btn = (action,label,cls='secondary',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
  function persist(touch=true){const s=current();if(s&&touch)s.updated=Date.now();db.version=D.version;try{localStorage.setItem(KEY,JSON.stringify(db));if(storageError){storageError=false;document.querySelector('.storage-alert')?.remove();}}catch{storageError=true;if(!document.querySelector('.storage-alert'))app.insertAdjacentHTML('afterbegin',`<div class="storage-alert">本次未能保存，当前内容仍保留在页面中。${btn('retry-save','重试保存','mini-link')}</div>`);}}
  function toast(message,withUndo=false){clearTimeout(toastTimer);const t=document.getElementById('toast');t.innerHTML=e(message)+(withUndo?btn('undo','撤销',''): '');t.classList.add('visible');toastTimer=setTimeout(()=>t.classList.remove('visible'),4500);}
  function pause(){playing=null;clearTimeout(playTimer);document.querySelectorAll('[data-action="play"]').forEach(b=>{b.classList.remove('playing');b.textContent='▷';b.setAttribute('aria-pressed','false');});document.querySelectorAll('.sim-label').forEach(x=>x.remove());}
  function topbar(){return `<header class="topbar">${btn('home','<span class="brand-icon"></span>Music Map','brand','aria-label="Music Map 首页"')}<nav class="top-actions" aria-label="主要导航">${btn('history','我的发现','text-btn')}${btn('challenge','步数挑战 ↗','pill')}</nav></header>`;}
  function setPage(page){pause();drawer=false;document.getElementById('track-drawer')?.remove();document.body.append(document.getElementById('toast'));modalState=null;if(modal.open)modal.close();db.page=page;persist(false);render();window.scrollTo(0,0);}
  function render(){app.innerHTML=`${storageError?`<div class="storage-alert">本地记录读取或保存失败；当前可继续体验。${btn('retry-save','重试保存','mini-link')}</div>`:''}<div class="shell ${db.page==='map'?'map-shell':''}">${topbar()}<section id="page"></section></div>`;if(db.page==='map'&&current())renderMap();else if(db.page==='challenge')renderChallenge();else if(db.page==='history')renderHistory();else renderHome();}
  function renderHome(){document.getElementById('page').innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">FOLLOW A VOICE. FIND A WORLD.</div><h1>从一位喜欢的艺人，<br>听见<em>更多。</em></h1><p class="muted">顺着一首合作、一种相似的声音，<br>在音乐的关系里，偶遇下一个喜欢。</p>${current()&&current().status!=='complete'?`<div style="margin-top:18px">${btn('resume-active','继续上次旅程 →','text-btn')}</div>`:''}</div><div class="orbit-art" aria-hidden="true"><svg viewBox="0 0 400 400"><g fill="none" stroke="#bcb0c4" stroke-width=".8"><circle cx="200" cy="200" r="151"/><ellipse cx="200" cy="200" rx="151" ry="60" transform="rotate(-28 200 200)"/><ellipse cx="200" cy="200" rx="75" ry="151" transform="rotate(35 200 200)"/><path d="M70 260L200 200L245 60M200 200L305 309" stroke-dasharray="3 4"/></g><g fill="#b39cb5"><circle cx="60" cy="135" r="3"/><circle cx="337" cy="164" r="4"/><circle cx="165" cy="345" r="3"/></g></svg><span class="art-node main">林</span><span class="art-node n1">乔</span><span class="art-node n2">夏</span><span class="art-node n3">陆</span><span class="art-caption">每一次连接，都是新的可能</span></div></section><section class="start-section"><div class="section-heading"><h2>今天，从谁开始？</h2><span class="muted">${D.artists.length} 位示例艺人</span></div><label class="searchbox"><span aria-hidden="true">⌕</span><input id="artist-search" aria-label="搜索示例艺人" placeholder="搜索示例艺人，如 林间、乔屿" autocomplete="off"></label><div id="search-results" class="artist-list"></div></section><footer class="footline"><span>自由漫游 / 沿途发现 / 步数挑战</span><span>KEEP YOUR CURIOSITY.</span></footer>`;search('');}
  function search(q){const list=D.artists.filter(a=>a.name.includes(q.trim()));document.getElementById('search-results').innerHTML=list.length?list.map(a=>`<button class="artist-card" data-action="start" data-id="${a.id}">${avatar(a.id)}<span><strong>${e(a.name)}</strong><small>${e(a.tag)}</small></span></button>`).join(''):`<div class="blank">没有找到已收录的示例艺人。<br>试试「林间」或「乔屿」。</div>`;}
  function newSession(id,type='roam',target=null,returnRoamId=null){const s={id:crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`,type,start:id,target,status:'active',mode:'co',yaw:0,pitch:0,path:[{id,mode:'co',yaw:0,pitch:0}],events:[],saved:[],created:Date.now(),updated:Date.now(),version:D.version,returnRoamId};db.sessions.push(s);db.active=s.id;setPage('map');return s;}
  function start(id){const s=current();if(s?.type==='roam'&&s.status==='active'){openConfirm('开始新的探索？','当前探索会保存到“我的发现”，新旅程从空清单开始。','start-confirm',id);return;}newSession(id);}
  function renderMap(){const s=current(),id=last(s).id;document.getElementById('page').innerHTML=`<div class="map-heading"><div><div class="eyebrow">${s.type==='challenge'?'A LITTLE MUSICAL ADVENTURE':'YOUR MUSICAL UNIVERSE'}</div><h1>${s.type==='challenge'?`去遇见 ${e(name(s.target))}`:'让好奇心，带路。'}</h1></div>${s.type==='challenge'?`<div class="step-badge">${s.path.length-1} 步<span class="small-note" style="display:block">不赶时间</span></div>`:`<div class="mode-switch">${btn('mode','合作关系',`pill ${s.mode==='co'?'active':''}`,'data-mode="co"')}${btn('mode','风格联系',`pill ${s.mode==='style'?'active':''}`,'data-mode="style"')}</div>`}</div><div class="map-layout"><div class="map-area"><div class="globe" id="globe" aria-label="可拖动旋转的艺人关系网"><svg id="globe-lines" aria-hidden="true"></svg><button class="node center" data-action="center" aria-expanded="${drawer}" aria-controls="track-drawer">${avatar(id)}<span class="node-name">${e(name(id))}</span></button>${neighbors(s).map(edge=>{const next=other(edge,id);return `<button class="node orbit-node" data-action="move" data-id="${next}" aria-label="探索 ${e(name(next))}">${avatar(next)}<span class="node-name">${e(name(next))}</span></button>`;}).join('')}</div><p class="orbit-help">拖动旋转 · 点击周围艺人继续探索 · 点击中心听代表作</p><div class="map-controls">${btn('back','← 上一位','secondary',s.path.length===1?'disabled':'')}${btn('reset','⌂ 回到起点','secondary',s.path.length===1?'disabled':'')}${btn('relations','连接依据','text-btn')}</div></div><aside class="map-side"><p class="muted">${s.mode==='co'?'一起唱过，也许一起喜欢':'相似的声音，另一种惊喜'}</p><div class="neighbor-strip">${neighbors(s).map(edge=>{const next=other(edge,id);return btn('move',`${avatar(next,true)}${e(name(next))} ↗`,'neighbor-chip',`data-id="${next}"`);}).join('')||'<p class="muted">当前模式暂无收录关系，可以返回或换个模式。</p>'}</div></aside></div><div class="map-bottom">${btn('discover',`本次发现 <span class="count">${s.saved.length} 首</span> ↗`,'discover-btn')}<div class="map-footer">${s.type==='challenge'?btn('return-roam','返回漫游','primary'):btn('finish','结束探索','primary')}</div></div>`;positionNodes();bindDrag();if(drawer)renderDrawer();}
  function positionNodes(){const g=document.getElementById('globe');if(!g)return;const s=current(),w=g.clientWidth,h=g.clientHeight;const nodes=[...g.querySelectorAll('.orbit-node')];const coords=[];nodes.forEach((node,i)=>{const angle=i*2*Math.PI/Math.max(nodes.length,1)-1.1;let x=Math.cos(angle),y=Math.sin(angle)*.85,z=Math.sin(angle*2)*.4;const nx=x*Math.cos(s.yaw)+z*Math.sin(s.yaw),nz=-x*Math.sin(s.yaw)+z*Math.cos(s.yaw);const ny=y*Math.cos(s.pitch)-nz*Math.sin(s.pitch),depth=y*Math.sin(s.pitch)+nz*Math.cos(s.pitch);let px=nx*Math.min(w*.35,225),py=ny*h*.32;const radius=Math.hypot(px,py);if(radius<100){const factor=100/Math.max(radius,.1);px*=factor;py*=factor;}const scale=.85+(depth+1)*.1;node.style.transform=`translate(${px}px,${py}px) scale(${scale})`;node.style.opacity=String(.73+(depth+1)*.12);node.style.zIndex=depth>0?'4':'2';coords.push([w/2+px,h/2+py]);});const color=s.mode==='co'?'#bc9cad':'#8c92a9';document.getElementById('globe-lines').innerHTML=`<g fill="none" stroke="#c8becb" stroke-width=".65" opacity=".7"><ellipse cx="${w/2}" cy="${h/2}" rx="${w*.37}" ry="${h*.39}"/><ellipse cx="${w/2}" cy="${h/2}" rx="${w*.37}" ry="${h*.14}" transform="rotate(${s.yaw*20-24} ${w/2} ${h/2})"/><ellipse cx="${w/2}" cy="${h/2}" rx="${w*.16}" ry="${h*.39}" transform="rotate(${s.pitch*20+28} ${w/2} ${h/2})"/></g><g stroke="${color}" stroke-width="1" ${s.mode==='style'?'stroke-dasharray="3 5"':''}>${coords.map(([x,y])=>`<line x1="${w/2}" y1="${h/2}" x2="${x}" y2="${y}"/>`).join('')}</g><g fill="#b6a2b8">${Array.from({length:24},(_,i)=>{const a=i*2.399;return `<circle cx="${w/2+Math.cos(a)*w*(.25+(i%3)*.045)}" cy="${h/2+Math.sin(a)*h*.34}" r="${i%3===0?2:1}"/>`;}).join('')}</g>`;}
  function bindDrag(){const g=document.getElementById('globe');g.addEventListener('pointerdown',ev=>{if(busy)return;drag={x:ev.clientX,y:ev.clientY,yaw:current().yaw,pitch:current().pitch,moved:false};});g.addEventListener('pointermove',ev=>{if(!drag)return;const dx=ev.clientX-drag.x,dy=ev.clientY-drag.y;if(Math.hypot(dx,dy)>8){drag.moved=true;g.setPointerCapture(ev.pointerId);current().yaw=drag.yaw+dx*.008;current().pitch=Math.max(-1.1,Math.min(1.1,drag.pitch+dy*.006));positionNodes();}});const stop=()=>{if(drag?.moved){suppressClick=Date.now()+250;persist();}drag=null;};g.addEventListener('pointerup',stop);g.addEventListener('pointercancel',stop);g.addEventListener('pointerleave',ev=>{if(drag&&!g.hasPointerCapture(ev.pointerId))stop();});}
  function move(id){if(busy||Date.now()<suppressClick)return;const s=current();if(!s||s.status==='complete')return;const edge=neighbors(s).find(x=>other(x,last(s).id)===id);if(!edge)return;pause();drawer=false;document.getElementById('track-drawer')?.remove();busy=true;const node=document.querySelector(`.orbit-node[data-id="${id}"]`),g=document.getElementById('globe');if(node){g.classList.add('motion');node.style.transform='translate(0px,0px) scale(1.25)';node.style.zIndex='25';document.querySelector('.node.center').style.opacity='.12';}setTimeout(()=>{const from=last(s).id;last(s).mode=s.mode;last(s).yaw=s.yaw;last(s).pitch=s.pitch;s.path.push({id,edge:{...edge},mode:s.mode,yaw:0,pitch:0});s.events.push({type:'move',from,to:id,edge:{...edge}});s.yaw=0;s.pitch=0;busy=false;if(s.type==='challenge'&&id===s.target){s.status='complete';persist();renderMap();openRecap(s.id,true);}else{persist();renderMap();}},matchMedia('(prefers-reduced-motion: reduce)').matches?0:450);}
  function back(reset=false){const s=current();if(!s||s.path.length===1)return;pause();drawer=false;document.getElementById('track-drawer')?.remove();const from=last(s).id;if(reset)s.path=[s.path[0]];else s.path.pop();s.mode=s.type==='challenge'?'co':last(s).mode;s.yaw=last(s).yaw;s.pitch=last(s).pitch;s.events.push({type:reset?'reset':'back',from,to:last(s).id});persist();renderMap();}
  function renderDrawer(){document.getElementById('track-drawer')?.remove();const s=current(),id=last(s).id;document.body.insertAdjacentHTML('beforeend',`<aside id="track-drawer" class="play-drawer" aria-label="${e(name(id))} 的代表作"><div class="drawer-heading"><div><div class="eyebrow">A CLOSER LISTEN</div><h3 style="margin-top:7px">${e(name(id))} · 代表作</h3></div>${btn('center','×','close','aria-label="收起代表作"')}</div><p class="muted">模拟试听，不播放真实音乐。</p>${A[id].songs.map((_,i)=>track(`${id}-${i}`,`在 ${name(id)} 的代表作中留下`,s)).join('')}</aside>`);}
  function track(id,source,s){const song=songs[id],saved=s.saved.some(x=>x.id===id);return `<div class="track" data-track="${id}">${btn('play','▷','play',`data-id="${id}" aria-label="${song.missing?'暂无试听':'模拟试听'} ${e(song.title)}" aria-pressed="false" ${song.missing?'disabled':''}`)}<div class="track-info"><div class="track-title">${e(song.title)}</div><small>${song.artists.map(name).map(e).join(' / ')} · ${song.missing?'暂无试听':'模拟试听'}</small>${source?`<small>${e(source)}</small>`:''}</div>${btn('save',saved?'已留下':'＋ 留下',`save ${saved?'saved':''}`,`data-id="${id}" data-source="${e(source)}" aria-label="${saved?'移除':'留下'} ${e(song.title)}"`)}</div>`;}
  function toggleSave(id,source){const s=context();if(!s)return;const idx=s.saved.findIndex(x=>x.id===id);if(idx>=0){const item=s.saved.splice(idx,1)[0];undo={session:s.id,item,index:idx};toast('已从本次发现移除',true);}else{s.saved.push({id,sources:[source||'在本次探索中留下']});toast('已留下，稍后在本次发现重听');}s.updated=Date.now();persist(false);refreshSongs(s);}
  function refreshSongs(s){document.querySelectorAll('[data-action="save"]').forEach(b=>{const saved=s.saved.some(x=>x.id===b.dataset.id);b.textContent=saved?'已留下':'＋ 留下';b.classList.toggle('saved',saved);b.setAttribute('aria-label',`${saved?'移除':'留下'} ${songs[b.dataset.id].title}`);});document.querySelector('.discover-btn .count')?.replaceChildren(document.createTextNode(`${current()?.saved.length||0} 首`));if(modalState?.type==='recap'){pause();const opens=[...content.querySelectorAll('details')].map(x=>x.open),scroll=modal.scrollTop;renderRecap(s,modalState.result,modalState.live);content.querySelectorAll('details').forEach((x,i)=>x.open=opens[i]);modal.scrollTop=scroll;}}
  function openModal(state,html){pause();drawer=false;document.getElementById('track-drawer')?.remove();document.querySelector('.node.center')?.setAttribute('aria-expanded','false');modalState=state;content.innerHTML=html;modal.append(document.getElementById('toast'));if(!modal.open)modal.showModal();modal.scrollTop=0;}
  const modalHead=title=>`<div class="modal-head"><h2 id="modal-title">${title}</h2>${btn('close','×','close','aria-label="关闭面板"')}</div>`;
  function closeModal(){const result=modalState?.result;pause();document.body.append(document.getElementById('toast'));modalState=null;if(modal.open)modal.close();if(result)setPage('home');}
  function openConfirm(title,message,action,id=''){openModal({type:'confirm'},`${modalHead(title)}<p class="muted">${e(message)}</p><div class="modal-actions">${btn('close','取消')}${btn(action,'确认','primary',`data-id="${id}"`)}</div>`);}
  function openRelations(){const s=current(),id=last(s).id;openModal({type:'relations',id:s.id},`${modalHead(s.mode==='co'?'为什么相连？':'为什么声音相似？')}<p class="muted">以下为虚构数据，仅演示关系依据的展示方式。</p>${neighbors(s).map(edge=>`<section class="recap-section"><h3>${e(name(id))} ↔ ${e(name(other(edge,id)))}</h3><p class="muted">${e(edge.reason)}</p>${edge.song?track(edge.song,`通过 ${name(edge.a)} 与 ${name(edge.b)} 的合作作品留下`,s):'<p class="small-note">风格相似不表示有合作作品。</p>'}</section>`).join('')||'<div class="blank">当前没有已收录关系。</div>'}`);}
  function routeHTML(s){const events=s.type==='challenge'?s.path.slice(1).map((p,i)=>({type:'move',from:s.path[i].id,to:p.id,edge:p.edge})):s.events;if(!events.length)return '<div class="blank">还没有走到下一位。</div>';return events.map(ev=>ev.type==='move'?`<div class="route-row"><div class="route-artists">${e(name(ev.from))} → ${e(name(ev.to))}</div><div class="route-reason">${ev.edge.mode==='co'?'合作关系':'风格联系'} · ${e(ev.edge.reason)}</div>${ev.edge.song?track(ev.edge.song,`通过 ${name(ev.from)} 与 ${name(ev.to)} 的合作作品留下`,s):''}</div>`:`<div class="route-nav">↩ ${ev.type==='reset'?'返回起点':'返回'} ${e(name(ev.to))}，换个方向</div>`).join('');}
  function openRecap(id,result=false,live=false){const s=db.sessions.find(x=>x.id===id);openModal({type:'recap',id,result,live},'');renderRecap(s,result,live);content.querySelector('button')?.focus();}
  function renderRecap(s,result=false,live=false){const visited=s.type==='challenge'?[...new Set(s.path.map(x=>x.id))]:uniqueArtists(s);content.innerHTML=`${modalHead(result?'沿着音乐，遇见了你':live?'本次发现':s.type==='challenge'?'挑战回顾':'这一路，留下的喜欢')}${result?`<div class="success-head"><div class="success-orbit">${s.path.length-1}</div><h2>${s.path.length-1} 步到达！</h2><p class="muted">${e(name(s.start))} → ${e(name(s.target))}<br>每一次绕路，也有自己的风景。</p></div>`:`<p class="muted">${new Date(s.created).toLocaleDateString('zh-CN')} · 从 ${e(name(s.start))} 出发${s.type==='challenge'?` · 目标 ${e(name(s.target))}`:''}</p>`}<div class="stat-grid"><div class="stat"><b>${visited.length}</b><span>位途经艺人 · 已去重</span></div><div class="stat"><b>${s.saved.length}</b><span>首主动留下的歌曲</span></div></div><section class="recap-section"><h3>留下的歌曲</h3>${s.saved.length?s.saved.map(x=>track(x.id,x.sources.join('；'),s)).join(''):'<div class="blank">这次还没有留下歌曲。<br>路线仍在，喜欢可以慢慢发现。</div>'}</section><details ${result?'open':''}><summary>${s.type==='challenge'?'最终路线与连接作品':'我走过的路'} · ${s.type==='challenge'?s.path.length-1:s.events.filter(x=>x.type==='move').length} 段</summary>${routeHTML(s)}</details><details><summary>途经艺人 · ${visited.length} 位</summary>${visited.map(id=>`<div class="visited">${avatar(id,true)}<span>${e(name(id))}</span>${!live&&s.type==='roam'?btn('start', '从 TA 再出发 ↗','mini-link',`data-id="${id}"`):''}</div>`).join('')}</details><div class="modal-actions">${s.type==='challenge'?(s.status==='complete'?btn('challenge','再次挑战','primary'):btn('resume','继续挑战','primary',`data-id="${s.id}"`))+btn('return-roam','返回漫游','secondary',`data-id="${s.id}"`):btn('resume','继续本次探索','primary',`data-id="${s.id}"`)+btn('new-home','开始新探索')}</div><p class="small-note">记录仅保存在当前浏览器。清除浏览器数据后可能丢失。示例歌曲不提供真实音频。</p>`;}
  function renderHistory(){document.getElementById('page').innerHTML=`<div class="subpage"><div class="page-intro"><div class="eyebrow">SOUVENIRS OF YOUR CURIOSITY</div><h1>我的发现</h1><p>有些喜欢，值得再听一次。<br>这里收着你走过的路和随手留下的音乐。</p></div>${[...db.sessions].sort((a,b)=>b.updated-a.updated).map(s=>`<article class="history-card"><div class="history-top"><div><div class="tag">${s.type==='challenge'?'合作挑战':'自由漫游'} · ${s.status==='complete'?'已完成':s.status==='ended'?'已结束':'未完成'}</div><h3>${e(name(s.start))}${s.target?` → ${e(name(s.target))}`:' 出发的旅程'}</h3><p class="small-note">${new Date(s.created).toLocaleDateString('zh-CN')} · 留下 ${s.saved.length} 首</p></div>${avatar(s.start)}</div><div class="history-actions">${btn('review','查看回顾','secondary',`data-id="${s.id}"`)}${s.status!=='complete'?btn('resume','继续','text-btn',`data-id="${s.id}"`):''}${btn('delete','删除','text-btn danger',`data-id="${s.id}"`)}</div></article>`).join('')||`<div class="blank">还没有发现记录。<br>从一位喜欢的艺人开始吧。<div style="margin-top:15px">${btn('home','开始探索','primary')}</div></div>`}<p class="small-note">仅当前浏览器保存，不跨设备同步。</p></div>`;}
  let challengeReturnId=current()?.type==='roam'?current().id:current()?.returnRoamId||null;
  function enterChallenge(){const s=current();challengeReturnId=s?.type==='roam'?s.id:s?.returnRoamId||null;setPage('challenge');}
  function renderChallenge(){document.getElementById('page').innerHTML=`<div class="subpage"><div class="page-intro"><div class="eyebrow">SIX DEGREES, ENDLESS POSSIBILITIES</div><h1>两位艺人之间，<br>藏着几首歌？</h1><p>选一个出发点和想遇见的人，沿着合作关系走过去。<br>没有倒计时，也不必走最短的路。</p></div><div class="form-card"><div class="field"><label for="challenge-start">01 / 从谁出发</label><select id="challenge-start">${D.artists.map(a=>`<option value="${a.id}">${e(a.name)} · ${e(a.tag)}</option>`).join('')}</select></div><div class="field"><label for="challenge-end">02 / 想遇见谁</label><select id="challenge-end">${D.artists.map(a=>`<option value="${a.id}" ${a.id==='f'?'selected':''}>${e(a.name)} · ${e(a.tag)}</option>`).join('')}</select></div><p id="challenge-error" class="error" role="alert"></p>${btn('begin-challenge','沿着合作，出发 →','primary wide')}<div class="tip">每经过一段合作关系，记为 1 步。<br>返回上一位会撤销这一步；可以随时回到漫游。</div><p class="small-note">全部为虚构示例。选择「孤岛来客」可体验关系未连通时的反馈。</p></div></div>`;}
  function reachable(a,b){const seen=new Set([a]),queue=[a];while(queue.length){const id=queue.shift();if(id===b)return true;edges.filter(x=>x.mode==='co'&&(x.a===id||x.b===id)).forEach(x=>{const next=other(x,id);if(!seen.has(next)){seen.add(next);queue.push(next);}});}return false;}
  function beginChallenge(){const a=document.getElementById('challenge-start').value,b=document.getElementById('challenge-end').value;const error=document.getElementById('challenge-error');if(a===b){error.textContent='出发点和终点相同，换一位想遇见的艺人吧。';return;}if(!reachable(a,b)){error.textContent='当前已收录关系暂未连通，请换个起点或终点。';return;}newSession(a,'challenge',b,challengeReturnId);}
  function resume(id){const s=db.sessions.find(x=>x.id===id);if(!s)return;if(s.version!==D.version){toast('本局数据版本不可用，请开始新的探索。');return;}db.active=id;if(s.status!=='complete')s.status='active';setPage('map');if(s.status==='complete')openRecap(s.id,true);}
  function returnRoam(id){const s=db.sessions.find(x=>x.id===id)||current();if(s?.type!=='challenge'){setPage('home');return;}s.updated=Date.now();const old=db.sessions.find(x=>x.id===s.returnRoamId);if(old){db.active=old.id;old.status='active';setPage('map');}else newSession(last(s).id);}
  document.addEventListener('input',ev=>{if(ev.target.id==='artist-search')search(ev.target.value);});
  document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled||busy)return;const action=b.dataset.action,id=b.dataset.id,s=current();switch(action){
    case 'home':setPage('home');break;
    case 'new-home':if(context()?.type==='roam'){context().status='ended';context().updated=Date.now();persist(false);}setPage('home');break;
    case 'history':setPage('history');break;
    case 'start':start(id);break;
    case 'start-confirm':if(s?.type==='roam'){s.status='ended';s.updated=Date.now();}newSession(id);break;
    case 'resume-active':if(s)resume(s.id);break;
    case 'resume':resume(id);break;
    case 'challenge':enterChallenge();break;
    case 'begin-challenge':beginChallenge();break;
    case 'move':move(id);break;
    case 'center':if(Date.now()<suppressClick)break;pause();drawer=!drawer;document.querySelector('.node.center')?.setAttribute('aria-expanded',String(drawer));if(drawer)renderDrawer();else document.getElementById('track-drawer')?.remove();break;
    case 'mode':if(s.type==='challenge')break;pause();drawer=false;document.getElementById('track-drawer')?.remove();s.mode=b.dataset.mode;persist();renderMap();break;
    case 'back':back();break;
    case 'reset':if(s.type==='challenge')openConfirm('回到本局起点？','当前路线和步数会重置，已留下的歌曲会保留。','reset-confirm');else back(true);break;
    case 'reset-confirm':closeModal();back(true);break;
    case 'relations':openRelations();break;
    case 'discover':openRecap(s.id,false,true);break;
    case 'finish':s.status='ended';persist();openRecap(s.id);break;
    case 'close':closeModal();break;
    case 'save':toggleSave(id,b.dataset.source);break;
    case 'undo':if(undo){const target=db.sessions.find(x=>x.id===undo.session);if(target&&!target.saved.some(x=>x.id===undo.item.id)){target.saved.splice(undo.index,0,undo.item);target.updated=Date.now();persist(false);if(context()?.id===target.id)refreshSongs(target);}undo=null;toast('已恢复');}break;
    case 'play':if(songs[id].missing)break;if(playing===id){pause();break;}pause();playing=id;document.querySelectorAll(`[data-action="play"][data-id="${id}"]`).forEach(x=>{x.classList.add('playing');x.textContent='Ⅱ';x.setAttribute('aria-pressed','true');x.parentElement.querySelector('.track-info').insertAdjacentHTML('beforeend','<span class="sim-label">正在模拟试听 · 无音频</span>');});playTimer=setTimeout(pause,8000);break;
    case 'review':{const rec=db.sessions.find(x=>x.id===id);openRecap(id,rec.type==='challenge'&&rec.status==='complete');break;}
    case 'return-roam':returnRoam(id);break;
    case 'delete':{const rec=db.sessions.find(x=>x.id===id);openConfirm('删除这条记录？',`将删除从 ${name(rec.start)} 出发的这次记录与其中留下的歌曲，其他记录不受影响。`,'delete-confirm',id);break;}
    case 'delete-confirm':db.sessions=db.sessions.filter(x=>x.id!==id);if(db.active===id)db.active=null;closeModal();persist(false);setPage('history');toast('已删除这条记录');break;
    case 'retry-save':persist(false);if(!storageError)toast('已保存当前记录');break;
  }});
  modal.addEventListener('cancel',ev=>{ev.preventDefault();closeModal();});
  window.addEventListener('resize',positionNodes);window.addEventListener('pagehide',()=>{pause();persist(false);});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
  render();if(db.page==='map'&&current()?.status==='complete')openRecap(current().id,true);
})();
